from pathlib import Path

stage = Path('live-aar-v2/StageV2.cs')
bridge = Path('live-aar-v2/BridgeV2.cs')
entry = Path('live-aar-v2/LiveAarV2.cs')

s = stage.read_text(encoding='utf-8')
s = s.replace('        private object _damageMat;\n', '        private object _damageMat;\n        private object _ammoMat;\n        private object _backdropMat;\n')
s = s.replace('            _mainMat = _mainGrayMat = _spallMat = _jetMat = _damageMat = null;', '            _mainMat = _mainGrayMat = _spallMat = _jetMat = _damageMat = _ammoMat = _backdropMat = null;')
s = s.replace('            FitCameras();\n            CreateShotLines(shot, vehicleTr, stageTr);', '            FitCameras();\n            CreateBackdrop();\n            CreateShotLines(shot, vehicleTr, stageTr);')
s = s.replace(
'''            _damageMat = U.SolidMaterial(1f, .24f, .025f, 1f);\n            AddResource(_mainMat); AddResource(_mainGrayMat); AddResource(_spallMat); AddResource(_jetMat); AddResource(_damageMat);''',
'''            _damageMat = U.SolidMaterial(1f, .24f, .025f, 1f);\n            _ammoMat = U.SolidMaterial(1f, .72f, .06f, 1f);\n            _backdropMat = U.SolidMaterial(.005f, .006f, .008f, 1f);\n            U.DisableCulling(_backdropMat);\n            AddResource(_mainMat); AddResource(_mainGrayMat); AddResource(_spallMat); AddResource(_jetMat); AddResource(_damageMat); AddResource(_ammoMat); AddResource(_backdropMat);''')

old_native = '''                if (hasRule && rule.Hidden) continue;\n                if (hasRule && rule.HighlightOnly && !rule.Highlighted) continue;\n\n                int layer = _aarLayer;\n                if (directHit || ammo || (hasRule && rule.Xrayed)) layer = _xrayLayer;\n\n                object mats = R.Get(sr, "sharedMaterials");\n                if (hasRule && rule.SwitchMaterials && rule.AarMaterial != null)\n                    mats = U.MaterialArray(rule.AarMaterial, Math.Max(1, U.ArrayLen(mats)));\n                else if (directHit && _damageMat != null)\n                    mats = U.MaterialArray(_damageMat, Math.Max(1, U.ArrayLen(mats)));'''
new_native = '''                if (hasRule && rule.Hidden) continue;\n\n                // Live AAR shows the complete native AAR/X-ray set. Filtering\n                // HighlightedOnly visuals was hiding crew/internal components.\n                int layer = _xrayLayer;\n\n                object mats = R.Get(sr, "sharedMaterials");\n                if (directHit && _damageMat != null)\n                    mats = U.MaterialArray(_damageMat, Math.Max(1, U.ArrayLen(mats)));\n                else if (hasRule && rule.SwitchMaterials && rule.AarMaterial != null)\n                    mats = U.MaterialArray(rule.AarMaterial, Math.Max(1, U.ArrayLen(mats)));\n                else if (ammo && _ammoMat != null)\n                    mats = U.MaterialArray(_ammoMat, Math.Max(1, U.ArrayLen(mats)));'''
if old_native not in s:
    raise RuntimeError('CloneNative block not found')
s = s.replace(old_native, new_native)

fit_start = s.index('        private void FitCameras()')
fit_end = s.index('        private void ConfigureCamera(', fit_start)
fit = '''        private void FitCameras()\n        {\n            object rootTr = R.Get(_root, "transform");\n            List<object> rs = U.Components(_root, U.RendererType, true);\n            List<float> xs = new List<float>();\n            List<float> ys = new List<float>();\n            List<float> zs = new List<float>();\n            List<float> reaches = new List<float>();\n\n            for (int i = 0; i < rs.Count; i++)\n            {\n                object rr = rs[i];\n                if (rr == null || !R.Bool(rr, "enabled", true)) continue;\n                string tn = rr.GetType().Name.ToLowerInvariant();\n                string rn = (R.Str(rr, "name") ?? "").ToLowerInvariant();\n                if (tn.Contains("line") || rn.Contains("trace") || rn.Contains("backdrop")) continue;\n\n                object b = R.Get(rr, "bounds");\n                object cc = b == null ? null : R.Get(b, "center");\n                object e = b == null ? null : R.Get(b, "extents");\n                if (cc == null || e == null) continue;\n                float er = U.Mag(e);\n                if (er < .02f || er > 8.5f) continue;\n\n                object lc = R.Call(rootTr, "InverseTransformPoint", cc);\n                if (lc == null || U.Mag(lc) > 12f) continue;\n                xs.Add(U.X(lc)); ys.Add(U.Y(lc)); zs.Add(U.Z(lc));\n                reaches.Add(er);\n            }\n\n            object center = R.Get(rootTr, "position");\n            float radius = 2.6f;\n            if (xs.Count > 0)\n            {\n                xs.Sort(); ys.Sort(); zs.Sort(); reaches.Sort();\n                int m = xs.Count / 2;\n                float mx = xs[m], my = ys[m], mz = zs[m];\n                center = R.Call(rootTr, "TransformPoint", U.V(mx, my, mz));\n\n                List<float> distances = new List<float>();\n                for (int i = 0; i < xs.Count; i++)\n                {\n                    float dx = xs[i] - mx, dy = ys[i] - my, dz = zs[i] - mz;\n                    distances.Add((float)Math.Sqrt(dx*dx + dy*dy + dz*dz));\n                }\n                distances.Sort();\n                int p = (int)Math.Floor((distances.Count - 1) * .86f);\n                if (p < 0) p = 0;\n                float spatial = distances[p];\n                int ep = (int)Math.Floor((reaches.Count - 1) * .80f);\n                if (ep < 0) ep = 0;\n                float extent = reaches[ep];\n                radius = spatial + extent * .72f;\n                if (radius < 1.9f) radius = 1.9f;\n                if (radius > 4.9f) radius = 4.9f;\n            }\n\n            _center = center;\n            _radius = radius;\n\n            object camPos = U.Add(center, U.V(radius*1.42f, radius*.34f, -radius*2.22f));\n            _baseCam = U.Camera("GHPC_LiveAAR_V21_BaseCamera");\n            object bgo = R.Get(_baseCam, "gameObject"); _created.Add(bgo);\n            object bt = R.Get(bgo, "transform"); R.Set(bt, "position", camPos); R.Call(bt, "LookAt", center);\n            ConfigureCamera(_baseCam, U.Mask(_aarLayer), 50f, false);\n\n            _xrayCam = U.Camera("GHPC_LiveAAR_V21_XrayCamera");\n            object xgo = R.Get(_xrayCam, "gameObject"); _created.Add(xgo);\n            object xt = R.Get(xgo, "transform"); R.Set(xt, "position", camPos); R.Set(xt, "rotation", R.Get(bt, "rotation"));\n            ConfigureCamera(_xrayCam, U.Mask(_xrayLayer), 51f, true);\n\n            int both = U.Mask(_aarLayer) | U.Mask(_xrayLayer);\n            object l1 = U.PointLight("GHPC_LiveAAR_V21_Key", U.Add(center, U.V(radius*1.0f, radius*1.15f, -radius*.85f)), radius*5f, 2.35f, both);\n            object l2 = U.PointLight("GHPC_LiveAAR_V21_Fill", U.Add(center, U.V(-radius*.85f, radius*.30f, radius*.85f)), radius*4f, .95f, both);\n            if (l1 != null) _created.Add(l1); if (l2 != null) _created.Add(l2);\n        }\n\n        private void CreateBackdrop()\n        {\n            if (_baseCam == null || _backdropMat == null) return;\n            object go = U.CameraBackdrop("GHPC_LiveAAR_V21_Backdrop", _baseCam, _aarLayer, _backdropMat);\n            if (go != null) _created.Add(go);\n        }\n\n'''
s = s[:fit_start] + fit + s[fit_end:]
s = s.replace('            R.Set(cam, "fieldOfView", 28f);', '            R.Set(cam, "fieldOfView", 31f);')
s = s.replace('            float py=96f;', '            float py=92f;')
s = s.replace('            int max = Math.Min(36, children.Count);', '            int max = Math.Min(14, children.Count);')
s = s.replace('            pts = CleanAndClamp(pts, child ? _radius*1.25f : _radius*1.7f);', '            pts = CleanAndClamp(pts, child ? _radius*1.05f : _radius*1.50f);')
s = s.replace('            if (child && length < .08f) return null;', '            if (child && length < .16f) return null;')
s = s.replace('            float width=Math.Max(.006f,_radius*.0032f);', '            float width=Math.Max(.0045f,_radius*.0022f);')
s = s.replace('                    rule.Highlighted=hit||R.Bool(av,"Highlighted",false);', '                    rule.Highlighted=true;')
stage.write_text(s, encoding='utf-8')

b = bridge.read_text(encoding='utf-8')
marker = '        internal static object PointLight(string name, object pos, float range, float intensity, int mask)'
helper = '''        internal static void DisableCulling(object material)\n        {\n            if (material == null) return;\n            try { R.Call(material, "SetInt", "_Cull", 0); } catch { }\n            try { R.Call(material, "SetFloat", "_Cull", 0f); } catch { }\n        }\n\n        internal static object QEuler(float x, float y, float z)\n        {\n            Init();\n            return R.CallStatic(_quat, "Euler", x, y, z);\n        }\n\n        internal static object CameraBackdrop(string name, object camera, int layer, object material)\n        {\n            Init();\n            if (camera == null || material == null) return null;\n            Type pt = R.Find("UnityEngine.PrimitiveType");\n            if (pt == null) return null;\n            object quadType;\n            try { quadType = Enum.Parse(pt, "Quad"); } catch { return null; }\n            object go = R.CallStatic(_go, "CreatePrimitive", quadType);\n            if (go == null) return null;\n            R.Set(go, "name", name);\n            R.Set(go, "layer", layer);\n            object tr = R.Get(go, "transform");\n            object camGo = R.Get(camera, "gameObject");\n            object camTr = camGo == null ? null : R.Get(camGo, "transform");\n            if (tr == null || camTr == null) return go;\n            R.Call(tr, "SetParent", camTr, false);\n            R.Set(tr, "localPosition", V(0f, 0f, 70f));\n            object rot = QEuler(0f, 180f, 0f);\n            if (rot != null) R.Set(tr, "localRotation", rot);\n            R.Set(tr, "localScale", V(160f, 100f, 1f));\n            object mr = GetComponent(go, _meshRenderer);\n            if (mr != null) R.Set(mr, "sharedMaterial", material);\n            Type col = R.Find("UnityEngine.Collider");\n            object collider = col == null ? null : GetComponent(go, col);\n            if (collider != null) Destroy(collider);\n            return go;\n        }\n\n'''
if marker not in b:
    raise RuntimeError('Bridge insertion point missing')
b = b.replace(marker, helper + marker)
bridge.write_text(b, encoding='utf-8')

e = entry.read_text(encoding='utf-8')
e = e.replace('"2.0.0"', '"2.1.0"')
e = e.replace('GHPC Live AAR v2.0.0 loaded.', 'GHPC Live AAR v2.1.0 loaded.')
entry.write_text(e, encoding='utf-8')

print('Patched GHPC Live AAR sources to v2.1.0')
